import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// -------------------------------------------------------------------------
// Kernel 1: partial reduction. Each row is split across num_chunks blocks so
// the grid is large enough to fill all SMs. Each block computes the partial
// sum and partial sum-of-squares of its segment with a single vectorized
// pass over global memory, reduces across the block in shared memory, and
// writes a (sum, sumsq) pair into the partials buffer.
// -------------------------------------------------------------------------
.visible .entry layernorm_partial(
    .param .u64 x_ptr,
    .param .u64 partial_ptr,
    .param .s32 norm_size,
    .param .s32 num_chunks,
    .param .s32 seg_len
)
{
    .reg .pred %p<16>;
    .reg .u32 %r<40>;
    .reg .u64 %rd<32>;
    .reg .f32 %f<40>;
    .shared .align 4 .f32 reduce_sum[512];
    .shared .align 4 .f32 reduce_sq[512];
    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [partial_ptr];
    ld.param.s32 %r0, [norm_size];
    ld.param.s32 %r1, [num_chunks];
    ld.param.s32 %r2, [seg_len];
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %ctaid.x;
    // row = ctaid / num_chunks, chunk = ctaid % num_chunks
    div.u32 %r6, %r5, %r1;
    mul.lo.u32 %r7, %r6, %r1;
    sub.u32 %r8, %r5, %r7;
    // segment [start, end) within the row
    mul.lo.u32 %r9, %r8, %r2;
    add.u32 %r10, %r9, %r2;
    min.u32 %r10, %r10, %r0;
    // row base pointer
    cvt.u64.u32 %rd6, %r6;
    cvt.u64.s32 %rd7, %r0;
    mul.lo.u64 %rd6, %rd6, %rd7;
    shl.b64 %rd6, %rd6, 2;
    add.u64 %rd2, %rd0, %rd6;
    // number of full float4 groups in this segment
    sub.u32 %r11, %r10, %r9;
    shr.u32 %r12, %r11, 2;
    // disable vector path if row stride or base is not 16B aligned
    and.b32 %r18, %r0, 3;
    setp.ne.s32 %p0, %r18, 0;
    @%p0 mov.u32 %r12, 0;
    and.b64 %rd15, %rd0, 15;
    setp.ne.u64 %p1, %rd15, 0;
    @%p1 mov.u32 %r12, 0;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f24, 0f00000000;
    mov.f32 %f25, 0f00000000;
    mov.f32 %f26, 0f00000000;
    // 4x unrolled vector pass: r21 = tile span (4*ntid groups),
    // r19 = number of groups covered by full unrolled tiles
    shl.b32 %r21, %r3, 2;
    div.u32 %r20, %r12, %r21;
    mul.lo.u32 %r19, %r20, %r21;
    mov.u32 %r13, %r4;
P_VEC4_LOOP:
    setp.lt.u32 %p0, %r13, %r19;
    @!%p0 bra P_VEC4_DONE;
    shl.b32 %r14, %r13, 2;
    add.u32 %r14, %r14, %r9;
    cvt.u64.u32 %rd12, %r14;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd10, %rd2, %rd12;
    add.u32 %r15, %r13, %r3;
    shl.b32 %r14, %r15, 2;
    add.u32 %r14, %r14, %r9;
    cvt.u64.u32 %rd12, %r14;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd11, %rd2, %rd12;
    add.u32 %r15, %r15, %r3;
    shl.b32 %r14, %r15, 2;
    add.u32 %r14, %r14, %r9;
    cvt.u64.u32 %rd12, %r14;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd13, %rd2, %rd12;
    add.u32 %r15, %r15, %r3;
    shl.b32 %r14, %r15, 2;
    add.u32 %r14, %r14, %r9;
    cvt.u64.u32 %rd12, %r14;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd14, %rd2, %rd12;
    ld.global.v4.f32 {%f3, %f4, %f5, %f6}, [%rd10];
    ld.global.v4.f32 {%f28, %f29, %f30, %f31}, [%rd11];
    ld.global.v4.f32 {%f32, %f33, %f34, %f35}, [%rd13];
    ld.global.v4.f32 {%f36, %f37, %f38, %f39}, [%rd14];
    add.f32 %f1, %f1, %f3;
    add.f32 %f1, %f1, %f4;
    add.f32 %f1, %f1, %f5;
    add.f32 %f1, %f1, %f6;
    fma.rn.f32 %f2, %f3, %f3, %f2;
    fma.rn.f32 %f2, %f4, %f4, %f2;
    fma.rn.f32 %f2, %f5, %f5, %f2;
    fma.rn.f32 %f2, %f6, %f6, %f2;
    add.f32 %f20, %f20, %f28;
    add.f32 %f20, %f20, %f29;
    add.f32 %f20, %f20, %f30;
    add.f32 %f20, %f20, %f31;
    fma.rn.f32 %f24, %f28, %f28, %f24;
    fma.rn.f32 %f24, %f29, %f29, %f24;
    fma.rn.f32 %f24, %f30, %f30, %f24;
    fma.rn.f32 %f24, %f31, %f31, %f24;
    add.f32 %f21, %f21, %f32;
    add.f32 %f21, %f21, %f33;
    add.f32 %f21, %f21, %f34;
    add.f32 %f21, %f21, %f35;
    fma.rn.f32 %f25, %f32, %f32, %f25;
    fma.rn.f32 %f25, %f33, %f33, %f25;
    fma.rn.f32 %f25, %f34, %f34, %f25;
    fma.rn.f32 %f25, %f35, %f35, %f25;
    add.f32 %f22, %f22, %f36;
    add.f32 %f22, %f22, %f37;
    add.f32 %f22, %f22, %f38;
    add.f32 %f22, %f22, %f39;
    fma.rn.f32 %f26, %f36, %f36, %f26;
    fma.rn.f32 %f26, %f37, %f37, %f26;
    fma.rn.f32 %f26, %f38, %f38, %f26;
    fma.rn.f32 %f26, %f39, %f39, %f26;
    add.u32 %r13, %r13, %r21;
    bra P_VEC4_LOOP;
P_VEC4_DONE:
    // remaining vector groups not covered by full tiles
    add.u32 %r13, %r19, %r4;
P_VEC_LOOP:
    setp.lt.u32 %p0, %r13, %r12;
    @!%p0 bra P_VEC_DONE;
    shl.b32 %r14, %r13, 2;
    add.u32 %r14, %r14, %r9;
    cvt.u64.u32 %rd12, %r14;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd10, %rd2, %rd12;
    ld.global.v4.f32 {%f3, %f4, %f5, %f6}, [%rd10];
    add.f32 %f1, %f1, %f3;
    add.f32 %f1, %f1, %f4;
    add.f32 %f1, %f1, %f5;
    add.f32 %f1, %f1, %f6;
    fma.rn.f32 %f2, %f3, %f3, %f2;
    fma.rn.f32 %f2, %f4, %f4, %f2;
    fma.rn.f32 %f2, %f5, %f5, %f2;
    fma.rn.f32 %f2, %f6, %f6, %f2;
    add.u32 %r13, %r13, %r3;
    bra P_VEC_LOOP;
P_VEC_DONE:
    shl.b32 %r14, %r12, 2;
    add.u32 %r14, %r14, %r9;
    add.u32 %r14, %r14, %r4;
P_SCALAR_LOOP:
    setp.lt.u32 %p0, %r14, %r10;
    @!%p0 bra P_SCALAR_DONE;
    cvt.u64.u32 %rd12, %r14;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd10, %rd2, %rd12;
    ld.global.f32 %f3, [%rd10];
    add.f32 %f1, %f1, %f3;
    fma.rn.f32 %f2, %f3, %f3, %f2;
    add.u32 %r14, %r14, %r3;
    bra P_SCALAR_LOOP;
P_SCALAR_DONE:
    // combine the independent unrolled accumulators
    add.f32 %f1, %f1, %f20;
    add.f32 %f1, %f1, %f21;
    add.f32 %f1, %f1, %f22;
    add.f32 %f2, %f2, %f24;
    add.f32 %f2, %f2, %f25;
    add.f32 %f2, %f2, %f26;
    mov.u64 %rd7, reduce_sum;
    mov.u64 %rd8, reduce_sq;
    cvt.u64.u32 %rd12, %r4;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd9, %rd7, %rd12;
    add.u64 %rd11, %rd8, %rd12;
    st.shared.f32 [%rd9], %f1;
    st.shared.f32 [%rd11], %f2;
    bar.sync 0;
    shr.u32 %r15, %r3, 1;
P_REDUCE_LOOP:
    setp.eq.u32 %p0, %r15, 0;
    @%p0 bra P_REDUCE_DONE;
    setp.lt.u32 %p1, %r4, %r15;
    @%p1 add.u32 %r16, %r4, %r15;
    @%p1 cvt.u64.u32 %rd12, %r16;
    @%p1 shl.b64 %rd12, %rd12, 2;
    @%p1 add.u64 %rd13, %rd7, %rd12;
    @%p1 add.u64 %rd14, %rd8, %rd12;
    @%p1 ld.shared.f32 %f3, [%rd9];
    @%p1 ld.shared.f32 %f4, [%rd13];
    @%p1 add.f32 %f3, %f3, %f4;
    @%p1 st.shared.f32 [%rd9], %f3;
    @%p1 ld.shared.f32 %f5, [%rd11];
    @%p1 ld.shared.f32 %f6, [%rd14];
    @%p1 add.f32 %f5, %f5, %f6;
    @%p1 st.shared.f32 [%rd11], %f5;
    bar.sync 0;
    shr.u32 %r15, %r15, 1;
    bra P_REDUCE_LOOP;
P_REDUCE_DONE:
    setp.ne.u32 %p0, %r4, 0;
    @%p0 bra P_EXIT;
    ld.shared.f32 %f1, [%rd7];
    ld.shared.f32 %f2, [%rd8];
    // partials index = (row * num_chunks + chunk) * 2
    mul.lo.u32 %r17, %r6, %r1;
    add.u32 %r17, %r17, %r8;
    shl.b32 %r17, %r17, 1;
    cvt.u64.u32 %rd12, %r17;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd10, %rd1, %rd12;
    st.global.f32 [%rd10], %f1;
    add.u64 %rd10, %rd10, 4;
    st.global.f32 [%rd10], %f2;
P_EXIT:
    ret;
}
// -------------------------------------------------------------------------
// Kernel 2: finalize. One small block per row combines the partial sums and
// produces mean[row] and rstd[row] = 1 / sqrt(var + eps).
// -------------------------------------------------------------------------
.visible .entry layernorm_finalize(
    .param .u64 partial_ptr,
    .param .u64 mean_ptr,
    .param .u64 inv_ptr,
    .param .s32 norm_size,
    .param .s32 num_chunks,
    .param .f32 epsilon
)
{
    .reg .pred %p<8>;
    .reg .u32 %r<24>;
    .reg .u64 %rd<16>;
    .reg .f32 %f<24>;
    .shared .align 4 .f32 reduce_sum[512];
    .shared .align 4 .f32 reduce_sq[512];
    ld.param.u64 %rd0, [partial_ptr];
    ld.param.u64 %rd1, [mean_ptr];
    ld.param.u64 %rd2, [inv_ptr];
    ld.param.s32 %r0, [norm_size];
    ld.param.s32 %r1, [num_chunks];
    ld.param.f32 %f0, [epsilon];
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %ctaid.x;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.u32 %r5, %r3;
    // base partial pair index for this row
    mul.lo.u32 %r6, %r4, %r1;
F_ACC_LOOP:
    setp.lt.u32 %p0, %r5, %r1;
    @!%p0 bra F_ACC_DONE;
    add.u32 %r7, %r6, %r5;
    shl.b32 %r7, %r7, 1;
    cvt.u64.u32 %rd8, %r7;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd6, %rd0, %rd8;
    ld.global.f32 %f3, [%rd6];
    add.u64 %rd6, %rd6, 4;
    ld.global.f32 %f4, [%rd6];
    add.f32 %f1, %f1, %f3;
    add.f32 %f2, %f2, %f4;
    add.u32 %r5, %r5, %r2;
    bra F_ACC_LOOP;
F_ACC_DONE:
    mov.u64 %rd3, reduce_sum;
    mov.u64 %rd4, reduce_sq;
    cvt.u64.u32 %rd8, %r3;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd5, %rd3, %rd8;
    add.u64 %rd7, %rd4, %rd8;
    st.shared.f32 [%rd5], %f1;
    st.shared.f32 [%rd7], %f2;
    bar.sync 0;
    shr.u32 %r8, %r2, 1;
F_REDUCE_LOOP:
    setp.eq.u32 %p0, %r8, 0;
    @%p0 bra F_REDUCE_DONE;
    setp.lt.u32 %p1, %r3, %r8;
    @%p1 add.u32 %r9, %r3, %r8;
    @%p1 cvt.u64.u32 %rd8, %r9;
    @%p1 shl.b64 %rd8, %rd8, 2;
    @%p1 add.u64 %rd9, %rd3, %rd8;
    @%p1 add.u64 %rd10, %rd4, %rd8;
    @%p1 ld.shared.f32 %f3, [%rd5];
    @%p1 ld.shared.f32 %f4, [%rd9];
    @%p1 add.f32 %f3, %f3, %f4;
    @%p1 st.shared.f32 [%rd5], %f3;
    @%p1 ld.shared.f32 %f5, [%rd7];
    @%p1 ld.shared.f32 %f6, [%rd10];
    @%p1 add.f32 %f5, %f5, %f6;
    @%p1 st.shared.f32 [%rd7], %f5;
    bar.sync 0;
    shr.u32 %r8, %r8, 1;
    bra F_REDUCE_LOOP;
F_REDUCE_DONE:
    setp.ne.u32 %p0, %r3, 0;
    @%p0 bra F_EXIT;
    ld.shared.f32 %f1, [%rd3];
    ld.shared.f32 %f2, [%rd4];
    cvt.rn.f32.s32 %f5, %r0;
    div.rn.f32 %f6, %f1, %f5;
    div.rn.f32 %f7, %f2, %f5;
    mul.f32 %f8, %f6, %f6;
    sub.f32 %f7, %f7, %f8;
    mov.f32 %f9, 0f00000000;
    max.f32 %f7, %f7, %f9;
    add.f32 %f7, %f7, %f0;
    sqrt.rn.f32 %f10, %f7;
    mov.f32 %f11, 0f3F800000;
    div.rn.f32 %f12, %f11, %f10;
    cvt.u64.u32 %rd8, %r4;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd9, %rd1, %rd8;
    st.global.f32 [%rd9], %f6;
    add.u64 %rd9, %rd2, %rd8;
    st.global.f32 [%rd9], %f12;
F_EXIT:
    ret;
}
// -------------------------------------------------------------------------
// Kernel 3: normalization. Grid-stride over the whole tensor so the grid is
// independent of the (small) row count. Uses float4 loads/stores when the
// row size and pointers are 16B aligned, with a scalar fallback path.
// -------------------------------------------------------------------------
.visible .entry layernorm_forward(
    .param .u64 x_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u64 partial_ptr,
    .param .s32 norm_size,
    .param .s32 num_chunks,
    .param .s32 seg_len,
    .param .f32 epsilon
)
{
    .reg .pred %p<16>;
    .reg .u32 %r<48>;
    .reg .u64 %rd<40>;
    .reg .f32 %f<40>;
    .shared .align 4 .f32 reduce_sum[512];
    .shared .align 4 .f32 reduce_sq[512];
    .shared .align 4 .f32 row_stats[2];
    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [weight_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u64 %rd4, [partial_ptr];
    ld.param.s32 %r0, [norm_size];
    ld.param.s32 %r1, [num_chunks];
    ld.param.s32 %r2, [seg_len];
    ld.param.f32 %f14, [epsilon];
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %ctaid.x;
    // row = ctaid / num_chunks, chunk = ctaid % num_chunks
    div.u32 %r6, %r5, %r1;
    mul.lo.u32 %r7, %r6, %r1;
    sub.u32 %r8, %r5, %r7;
    // segment [start, end) within the row
    mul.lo.u32 %r9, %r8, %r2;
    add.u32 %r10, %r9, %r2;
    min.u32 %r10, %r10, %r0;
    // First fuse the finalize reduction into this kernel. Each block
    // reduces the partial pairs for its row, then thread 0 publishes
    // mean and rstd in shared memory for the normalization pass.
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.u32 %r11, %r4;
N_ACC_LOOP:
    setp.lt.u32 %p0, %r11, %r1;
    @!%p0 bra N_ACC_DONE;
    add.u32 %r12, %r7, %r11;
    shl.b32 %r12, %r12, 1;
    cvt.u64.u32 %rd16, %r12;
    shl.b64 %rd16, %rd16, 2;
    add.u64 %rd11, %rd4, %rd16;
    ld.global.f32 %f3, [%rd11];
    add.u64 %rd11, %rd11, 4;
    ld.global.f32 %f4, [%rd11];
    add.f32 %f1, %f1, %f3;
    add.f32 %f2, %f2, %f4;
    add.u32 %r11, %r11, %r3;
    bra N_ACC_LOOP;
N_ACC_DONE:
    mov.u64 %rd5, reduce_sum;
    mov.u64 %rd6, reduce_sq;
    cvt.u64.u32 %rd16, %r4;
    shl.b64 %rd16, %rd16, 2;
    add.u64 %rd7, %rd5, %rd16;
    add.u64 %rd8, %rd6, %rd16;
    st.shared.f32 [%rd7], %f1;
    st.shared.f32 [%rd8], %f2;
    bar.sync 0;
    shr.u32 %r13, %r3, 1;
N_REDUCE_LOOP:
    setp.eq.u32 %p0, %r13, 0;
    @%p0 bra N_REDUCE_DONE;
    setp.lt.u32 %p1, %r4, %r13;
    @%p1 add.u32 %r14, %r4, %r13;
    @%p1 cvt.u64.u32 %rd16, %r14;
    @%p1 shl.b64 %rd16, %rd16, 2;
    @%p1 add.u64 %rd9, %rd5, %rd16;
    @%p1 add.u64 %rd10, %rd6, %rd16;
    @%p1 ld.shared.f32 %f3, [%rd7];
    @%p1 ld.shared.f32 %f4, [%rd9];
    @%p1 add.f32 %f3, %f3, %f4;
    @%p1 st.shared.f32 [%rd7], %f3;
    @%p1 ld.shared.f32 %f5, [%rd8];
    @%p1 ld.shared.f32 %f6, [%rd10];
    @%p1 add.f32 %f5, %f5, %f6;
    @%p1 st.shared.f32 [%rd8], %f5;
    bar.sync 0;
    shr.u32 %r13, %r13, 1;
    bra N_REDUCE_LOOP;
N_REDUCE_DONE:
    mov.u64 %rd12, row_stats;
    setp.ne.u32 %p0, %r4, 0;
    @%p0 bra N_STATS_WAIT;
    ld.shared.f32 %f1, [%rd5];
    ld.shared.f32 %f2, [%rd6];
    cvt.rn.f32.s32 %f5, %r0;
    div.rn.f32 %f6, %f1, %f5;
    div.rn.f32 %f7, %f2, %f5;
    mul.f32 %f8, %f6, %f6;
    sub.f32 %f7, %f7, %f8;
    mov.f32 %f9, 0f00000000;
    max.f32 %f7, %f7, %f9;
    add.f32 %f7, %f7, %f14;
    sqrt.rn.f32 %f10, %f7;
    mov.f32 %f11, 0f3F800000;
    div.rn.f32 %f12, %f11, %f10;
    st.shared.f32 [%rd12], %f6;
    add.u64 %rd13, %rd12, 4;
    st.shared.f32 [%rd13], %f12;
N_STATS_WAIT:
    bar.sync 0;
    ld.shared.f32 %f0, [%rd12];
    add.u64 %rd13, %rd12, 4;
    ld.shared.f32 %f1, [%rd13];
    // Precompute the global base addresses for this row.
    cvt.u64.u32 %rd13, %r6;
    cvt.u64.s32 %rd14, %r0;
    mul.lo.u64 %rd13, %rd13, %rd14;
    shl.b64 %rd13, %rd13, 2;
    add.u64 %rd14, %rd0, %rd13;
    add.u64 %rd15, %rd3, %rd13;
    // Use float4 only when the row size and all participating pointers
    // preserve 16-byte alignment. seg_len is rounded to a multiple of 4.
    and.b32 %r13, %r0, 3;
    setp.ne.s32 %p0, %r13, 0;
    and.b64 %rd16, %rd0, 15;
    and.b64 %rd17, %rd1, 15;
